INSERT INTO "public"."execution_plans" VALUES ('plan_affected_orders_v1', 'pkg_battery_manufacturing', 'affected_orders', 1, 'PUBLISHED', '{"id": "plan_affected_orders_v1", "key": "affected_orders", "steps": [{"id": "s1", "type": "invoke_solver", "params": {"args": {"toDay": "{{slots.timeWindow}}", "baseId": "{{slots.base.objectId}}", "fromDay": "{{slots.timeWindow}}"}, "solverKey": "affected_orders"}}, {"id": "render", "type": "render_answer", "params": {"blocks": [{"rows": "{{steps.s1.output.data.rows}}", "type": "table", "columns": ["订单号", "客户", "型号", "数量", "交期"], "fromStep": "s1"}, {"type": "text", "markdown": "受影响订单共 {{steps.s1.output.data.count}} 张，明细见上表 ⟦ref:0⟧。"}]}}], "status": "PUBLISHED", "version": 1, "packageId": "pkg_battery_manufacturing"}');
INSERT INTO "public"."execution_plans" VALUES ('plan_capacity_feasibility_v1', 'pkg_battery_manufacturing', 'capacity_feasibility', 1, 'PUBLISHED', '{"id": "plan_capacity_feasibility_v1", "key": "capacity_feasibility", "steps": [{"id": "s1", "type": "resolve_slice", "params": {"args": {"modelId": "{{slots.model.objectId}}"}, "sliceKey": "model_capacity_network"}}, {"id": "s2", "type": "invoke_solver", "params": {"args": {"weeks": "{{slots.weeks}}", "modelId": "{{slots.model.objectId}}", "demandDelta": "{{slots.demandDelta}}"}, "solverKey": "capacity_forecast"}}, {"id": "s3", "type": "evaluate_rules", "params": {"payload": {"demandDelta": "{{slots.demandDelta}}"}, "ruleIds": ["C03"]}}, {"id": "render", "type": "render_answer", "params": {"blocks": [{"type": "kpi", "unit": "GWh", "label": "P50 产能", "value": "{{steps.s2.output.data.p50}}", "fromStep": "s2"}, {"type": "kpi", "unit": "GWh", "label": "P90 产能", "value": "{{steps.s2.output.data.p90}}", "fromStep": "s2"}, {"type": "kpi", "unit": "%", "label": "缺口比例", "value": "{{steps.s2.output.data.gapPct}}", "fromStep": "s2"}, {"type": "text", "markdown": "主要瓶颈为{{steps.s2.output.data.mainBottleneck}}，P50/P90 与缺口见上方指标 ⟦ref:0⟧⟦ref:1⟧⟦ref:2⟧。"}]}}], "status": "PUBLISHED", "version": 1, "packageId": "pkg_battery_manufacturing"}');
INSERT INTO "public"."execution_plans" VALUES ('plan_risk_root_cause_v1', 'pkg_battery_manufacturing', 'risk_root_cause', 1, 'PUBLISHED', '{"id": "plan_risk_root_cause_v1", "key": "risk_root_cause", "steps": [{"id": "s1", "type": "resolve_slice", "params": {"args": {"baseId": "{{slots.base.objectId}}"}, "sliceKey": "base_risk_profile"}}, {"id": "render", "type": "render_answer", "params": {"blocks": [{"type": "text", "fromStep": "s1", "markdown": "{{steps.s1.output.data.summary}} ⟦ref:0⟧"}]}}], "status": "PUBLISHED", "version": 1, "packageId": "pkg_battery_manufacturing"}');
INSERT INTO "public"."execution_plans" VALUES ('plan_adopt_mitigation_v1', 'pkg_battery_manufacturing', 'adopt_mitigation', 1, 'PUBLISHED', '{"id": "plan_adopt_mitigation_v1", "key": "adopt_mitigation", "steps": [{"id": "s1", "type": "evaluate_rules", "params": {"payload": {"baseId": "{{slots.base.objectId}}", "solutionName": "{{slots.solutionName}}"}, "ruleIds": ["C13"]}}, {"id": "s2", "type": "create_action_draft", "params": {"payload": {"baseId": "{{slots.base.objectId}}", "solutionName": "{{slots.solutionName}}"}, "actionType": "adopt_mitigation"}}, {"id": "render", "type": "render_answer", "params": {"blocks": [{"type": "action_draft", "draftId": "{{steps.s2.output.draftId}}", "summary": "已生成「{{slots.solutionName}}」处置方案草稿，待审批。", "actionType": "adopt_mitigation"}, {"type": "text", "markdown": "草稿已提交审批流程，本系统不会直接执行写操作。"}]}}], "status": "PUBLISHED", "version": 1, "packageId": "pkg_battery_manufacturing"}');


