INSERT INTO "public"."intent_definitions" VALUES ('int_affected_orders_v1', 'pkg_battery_manufacturing', 'affected_orders', 1, 'PUBLISHED', '{"id": "int_affected_orders_v1", "key": "affected_orders", "name": "受影响订单查询", "owner": "seed", "slots": [{"name": "base", "type": "objectRef", "required": true, "defaultFrom": "$.selectedObjects[0]", "description": "受影响的基地（Base 对象引用）", "clarifyPrompt": "请提供基地"}, {"name": "timeWindow", "type": "timeWindow", "required": false, "description": "时间窗（可选）"}], "planId": "plan_affected_orders_v1", "status": "PUBLISHED", "version": 1, "examples": ["影响哪些订单？", "常州停产影响哪些订单", "这个基地的订单交付受什么影响"], "createdAt": "2026-06-14T05:53:39.558Z", "packageId": "pkg_battery_manufacturing", "riskLevel": "COMPUTE", "updatedAt": "2026-06-14T05:53:39.558Z", "description": "查询某基地在给定时间窗内停产/降产时受影响的订单清单。", "enabledViews": "*"}');
INSERT INTO "public"."intent_definitions" VALUES ('int_capacity_feasibility_v1', 'pkg_battery_manufacturing', 'capacity_feasibility', 1, 'PUBLISHED', '{"id": "int_capacity_feasibility_v1", "key": "capacity_feasibility", "name": "需求增量能否承接", "owner": "seed", "slots": [{"name": "model", "type": "objectRef", "required": true, "description": "型号（Model 对象引用）"}, {"name": "demandDelta", "type": "number", "required": true, "description": "需求增量比例（0.2 表示 +20%）"}, {"name": "weeks", "type": "number", "required": false, "description": "周数，缺省 6"}], "planId": "plan_capacity_feasibility_v1", "status": "PUBLISHED", "version": 1, "examples": ["4680-NCM 加 20% 六周能不能接？", "M3P 增加 10% 产能够吗", "需求上调后能不能交付"], "createdAt": "2026-06-14T05:53:39.558Z", "packageId": "pkg_battery_manufacturing", "riskLevel": "COMPUTE", "updatedAt": "2026-06-14T05:53:39.558Z", "description": "判断某型号增加一定需求比例、给定周数内产能是否能承接。", "enabledViews": "*"}');
INSERT INTO "public"."intent_definitions" VALUES ('int_risk_root_cause_v1', 'pkg_battery_manufacturing', 'risk_root_cause', 1, 'PUBLISHED', '{"id": "int_risk_root_cause_v1", "key": "risk_root_cause", "name": "风险根因分析", "owner": "seed", "slots": [{"name": "base", "type": "objectRef", "required": true, "defaultFrom": "$.selectedObjects[0]", "description": "基地对象引用"}, {"name": "day", "type": "date", "required": false, "description": "日期（可选）"}], "planId": "plan_risk_root_cause_v1", "status": "PUBLISHED", "version": 1, "examples": ["为什么这天越线", "常州为什么风险高", "风险根因是什么"], "createdAt": "2026-06-14T05:53:39.558Z", "packageId": "pkg_battery_manufacturing", "riskLevel": "READ", "updatedAt": "2026-06-14T05:53:39.558Z", "description": "解释某基地在某天风险越线的根因。", "enabledViews": "*"}');
INSERT INTO "public"."intent_definitions" VALUES ('int_adopt_mitigation_v1', 'pkg_battery_manufacturing', 'adopt_mitigation', 1, 'PUBLISHED', '{"id": "int_adopt_mitigation_v1", "key": "adopt_mitigation", "name": "采纳处置方案", "owner": "seed", "slots": [{"name": "base", "type": "objectRef", "required": true, "defaultFrom": "$.selectedObjects[0]", "description": "基地对象引用"}, {"name": "solutionName", "type": "enum", "required": true, "enumValues": ["三班制", "外协", "调拨"], "description": "处置方案名"}], "planId": "plan_adopt_mitigation_v1", "status": "PUBLISHED", "version": 1, "examples": ["采纳常州的三班制方案", "执行外协方案", "采纳处置建议"], "createdAt": "2026-06-14T05:53:39.558Z", "packageId": "pkg_battery_manufacturing", "riskLevel": "ACTION_DRAFT", "updatedAt": "2026-06-14T05:53:39.558Z", "description": "把某基地的处置方案落为 Action 草稿提交审批（不直接执行）。", "enabledViews": "*"}');


