INSERT INTO "public"."scene_entries" VALUES ('scn_dash', 'demo', 'dash', '{"id": "scn_dash", "mode": "WORKFLOW_FIRST", "uiHints": {"placeholder": "问问经营数据，如：本月计划达成率怎么样？", "suggestedQuestions": ["4680-NCM 加 20% 六周能不能接？", "对比一下储能基地和动力基地的平均利用率"]}, "viewKey": "dash", "tenantId": "demo", "preloadedHistory": [{"date": "2026-06-21", "answer": "2026-06 计划达成率 94.0%，较年初（88.0%）提升 6 个百分点；常州/合肥两基地贡献最大。", "question": "本月计划达成率怎么样？", "trustLevel": "VERIFIED_WORKFLOW"}, {"date": "2026-06-08", "answer": "2026-Q2 已交付订单准交率 85.0%（51/60 按期），9 单曾延期，其中 7 单经处置方案挽回至 ≤2 天。", "question": "上季度准交率多少？", "trustLevel": "VERIFIED_WORKFLOW"}, {"date": "2026-01-12", "answer": "2025-11/12 受正极到货危机与部分基地检修叠加影响，产出环比下降约 8%；2026-01 起恢复爬坡。", "question": "12 月产出为什么下凹？", "trustLevel": "VERIFIED_WORKFLOW"}, {"date": "2026-05-30", "answer": "近 12 个月 Action 审计共 200 条，其中 164 条已执行（EXECUTED），22 条被驳回，详见运营回顾页。", "question": "今年累计执行了多少工单？", "trustLevel": "VERIFIED_WORKFLOW"}]}');
INSERT INTO "public"."scene_entries" VALUES ('scn_risk', 'demo', 'risk', '{"id": "scn_risk", "mode": "WORKFLOW_FIRST", "uiHints": {"placeholder": "针对选中基地提问，如：影响哪些订单？", "suggestedQuestions": ["影响哪些订单？", "为什么这天越线", "采纳常州的三班制方案"]}, "viewKey": "risk", "tenantId": "demo", "preloadedHistory": [{"date": "2025-11-26", "answer": "常州基地 2025-11 到货危机窗口内受影响订单 4 张（SO-20007 等），其中 3 张经提前备料方案挽回。", "question": "影响哪些订单？", "trustLevel": "VERIFIED_WORKFLOW"}, {"date": "2025-11-20", "answer": "根因：正极材料到货延迟 5 天导致齐套断档，叠加产线利用率高位运行；详见历史处置案例 CASE-007。", "question": "为什么这天越线？", "trustLevel": "VERIFIED_WORKFLOW"}, {"date": "2025-11-21", "answer": "已生成「提前备料」处置 Action 草稿并经审批执行（act_lh 审计可查），风险曲线于 12-01 消解。", "question": "采纳常州的提前备料方案", "trustLevel": "VERIFIED_WORKFLOW"}]}');
INSERT INTO "public"."scene_entries" VALUES ('scn_order', 'demo', 'order', '{"id": "scn_order", "mode": "WORKFLOW_FIRST", "uiHints": {"placeholder": "查订单，如：影响哪些订单？", "suggestedQuestions": ["影响哪些订单？"]}, "viewKey": "order", "tenantId": "demo"}');
INSERT INTO "public"."scene_entries" VALUES ('scn_graph', 'demo', 'graph', '{"id": "scn_graph", "mode": "AGENT_FIRST", "uiHints": {"placeholder": "围绕本体随便问（探索性回答，AGENT 信任级）", "suggestedQuestions": ["哪个客户的订单延期风险最高", "精度为什么越用越准？"]}, "viewKey": "graph", "tenantId": "demo", "defaultAgentId": "agt_seed_analyst", "preloadedHistory": [{"date": "2026-05-19", "answer": "经验回看：蓝海储能集中在 S192-LFP 且交付窗口贴近检修月，历史延期 3 次居首（数字均有工具溯源）。", "question": "哪个客户的订单延期风险最高", "trustLevel": "AGENT_EXPLORATORY"}, {"date": "2026-06-12", "answer": "校准闭环 52 周内将 MAPE 从 12% 收敛到 7%：6 次参数生效、2 次按方法学门槛拒绝（漂移闸门/回测不足）。", "question": "精度为什么越用越准？", "trustLevel": "AGENT_EXPLORATORY"}]}');
INSERT INTO "public"."scene_entries" VALUES ('scn_plan_audit', 'demo', 'plan-audit', '{"id": "scn_plan_audit", "mode": "WORKFLOW_ONLY", "uiHints": {"placeholder": "规划体检（基线 = 最近定稿 S&OP 版本）", "suggestedQuestions": ["最近定稿版本体检结果如何？"]}, "viewKey": "plan-audit", "tenantId": "demo", "preloadedHistory": [{"date": "2026-06-25", "answer": "基线 = 2026-06 V12：总评 92 分通过；现金垫 58 亿高于底线，齐套缺口 654 吨为软性提示。", "question": "最近定稿版本体检结果如何？", "trustLevel": "VERIFIED_WORKFLOW"}, {"date": "2026-05-11", "answer": "C08 外协比例红线现行 v1.3 ≤20%（年初 v1.0 为 ≤25%，经三次复盘收紧），当前实际 14.2%。", "question": "外协比例现在卡多少？", "trustLevel": "VERIFIED_WORKFLOW"}]}');
INSERT INTO "public"."scene_entries" VALUES ('scn_plan_generate', 'demo', 'plan-generate', '{"id": "scn_plan_generate", "mode": "WORKFLOW_FIRST", "uiHints": {"placeholder": "方案生成相关问题", "suggestedQuestions": ["保毛利和保规模怎么选？"]}, "viewKey": "plan-generate", "tenantId": "demo", "preloadedHistory": [{"date": "2026-02-18", "answer": "按当前目标面板：均衡方案（B+A 混合）综合分最高；保毛利路径现金垫最厚但份额增长受限。", "question": "保毛利和保规模怎么选？", "trustLevel": "VERIFIED_WORKFLOW"}, {"date": "2026-02-20", "answer": "2026-02 采纳「均衡」方案（Action 已执行），营收目标 +18%、毛利率底线 13.5% 保持不变。", "question": "上次采纳的是哪个方案？", "trustLevel": "VERIFIED_WORKFLOW"}]}');
INSERT INTO "public"."scene_entries" VALUES ('scn_project_sim', 'demo', 'project-sim', '{"id": "scn_project_sim", "mode": "WORKFLOW_FIRST", "uiHints": {"placeholder": "项目推演相关问题", "suggestedQuestions": ["4680-NCM 加 20% 六周能不能接？"]}, "viewKey": "project-sim", "tenantId": "demo", "preloadedHistory": [{"date": "2026-04-15", "answer": "P50 口径可承接，P90 口径缺口 3.2%；瓶颈在化成工序，建议增开夜班或外协 8%。", "question": "4680-NCM 加 20% 六周能不能接？", "trustLevel": "VERIFIED_WORKFLOW"}, {"date": "2026-04-18", "answer": "需求上修后季度供需缺口扩大至 4.1 万套，已按 C21 提报 S&OP 议程（V10 决议增开宜宾二线）。", "question": "S192 储能需求上修 15% 影响多大？", "trustLevel": "VERIFIED_WORKFLOW"}]}');
INSERT INTO "public"."scene_entries" VALUES ('scn_sop_balance', 'demo', 'sop-balance', '{"id": "scn_sop_balance", "mode": "WORKFLOW_FIRST", "uiHints": {"placeholder": "S&OP 月度平衡相关问题", "suggestedQuestions": []}, "viewKey": "sop-balance", "tenantId": "demo"}');
INSERT INTO "public"."scene_entries" VALUES ('scn_review', 'demo', 'review', '{"id": "scn_review", "mode": "WORKFLOW_FIRST", "uiHints": {"placeholder": "回顾一年运营，如：到货危机当时是怎么闭环的？", "suggestedQuestions": ["到货危机当时是怎么闭环的？", "S&OP 达成率趋势如何？"]}, "viewKey": "review", "tenantId": "demo", "preloadedHistory": [{"date": "2025-12-05", "answer": "2025-11-18 风险越线 → 11-21 采纳提前备料（Action 执行）→ 12-01 曲线消解 → C16 覆盖天数 3→5 天收紧 → MAPE 回弹 +1.8pct 后继续收敛。", "question": "到货危机当时是怎么闭环的？", "trustLevel": "VERIFIED_WORKFLOW"}, {"date": "2026-06-28", "answer": "V1（88%）至 V12（94%）逐月爬升，与月度实绩同源勾稽；两次明显波动分别对应检修季与到货危机。", "question": "S&OP 达成率趋势如何？", "trustLevel": "VERIFIED_WORKFLOW"}]}');
