INSERT INTO "public"."scene_entries" VALUES ('scn_01KV2B8YXX8NRGMYDQSPSRWKXP', 'demo', 'ent-risk-s02_affected', '{"id": "scn_01KV2B8YXX8NRGMYDQSPSRWKXP", "mode": "AGENT_FIRST", "uiHints": {"placeholder": "交期风险与受影响订单：试试「常州基地影响哪些订单？」", "suggestedQuestions": ["常州基地影响哪些订单？"]}, "viewKey": "ent-risk-s02_affected", "tenantId": "demo", "updatedAt": "2026-06-14T05:57:08.548Z", "defaultAgentId": "agt_01KV2B8YXPDNH7ZND4B3SYXY7K", "preloadedHistory": [{"date": "2026-06-14", "answer": "经跨 6 域切片 order_fulfillment_360 检索 + affected_orders 求解（snapshot 1.14）。【过程】① 切片自每张订单出发跨 产品→工厂→工艺→设备→供给→商务 检索完整履约链（受影响单并集 145 节点）；② affected_orders 在交期窗口 [−7,+14] 内按 problems 四类（交期/毛利/齐套/信用）归并。【数据】常州在手订单经 A6 行级过滤后入池；命中受影响 45 单。【结果】受影响 45 单，典型如 SO-10799（蓝海储能，L148-LFP，预计延误 2 天，影响度 0.4）；每个数字可下钻溯源。", "question": "常州基地影响哪些订单？", "trustLevel": "VERIFIED_WORKFLOW"}]}');
INSERT INTO "public"."scene_entries" VALUES ('scn_01KV2B8YYBPQ2H3DH0PFZ0Q8CF', 'demo', 'ent-audit-s04_audit', '{"id": "scn_01KV2B8YYBPQ2H3DH0PFZ0Q8CF", "mode": "AGENT_FIRST", "uiHints": {"placeholder": "月度规划体检：试试「现金垫 45 亿过得了体检吗？」", "suggestedQuestions": ["现金垫 45 亿过得了体检吗？"]}, "viewKey": "ent-audit-s04_audit", "tenantId": "demo", "updatedAt": "2026-06-14T05:57:08.577Z", "defaultAgentId": "agt_01KV2B8YY3GYAJAX7ZWM79SD6G", "preloadedHistory": [{"date": "2026-06-14", "answer": "经跨 6 域切片检索代表订单跨域输入 + plan_audit 体检。【过程】① 对每型号交期最早订单经切片检索供给齐套/商务信用/工厂产能等跨域输入（代表订单 46 节点）；② plan_audit 按硬矛盾(H)/软风险(S)规则口径打分。【数据】需求 480 万套（细分 220/170/90 自洽）、供给 450、长协覆盖 0.85、现金垫 55 亿、毛利目标 18%。【结果】总评 34/100，结论「不通过」，硬矛盾 2 项；明细见规划体检页。", "question": "现金垫 55 亿、毛利目标 18% 过得了体检吗？", "trustLevel": "VERIFIED_WORKFLOW"}]}');


