INSERT INTO "public"."skills" VALUES ('skl_seed_capacity', 'demo', 'capacity_analysis', 1, 'PUBLISHED', '{"id": "skl_seed_capacity", "key": "capacity_analysis", "body": "# 产能分析\n\n1. 先看型号认证状态（量产/认证中）。\n2. P50 看均衡产线，P90 看保守口径。\n3. 缺口为负时优先评估外协与排程平移。", "name": "产能分析方法论", "status": "PUBLISHED", "summary": "产能金字塔口径与 P50/P90 解读要点。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YQ4GF3H86PJGBG4QR3R', 'demo', 's01_feasibility', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YQ4GF3H86PJGBG4QR3R", "key": "s01_feasibility", "body": "## 目的\n解读产能可承接结论的口径。\n## 适用边界\n适用：对比 P50/P90、解释认证系数或爬坡折减时。不适用：产能数值计算本身（应由 capacity_forecast 求解器计算）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "订单可承接性解读", "status": "PUBLISHED", "summary": "解读产能可承接结论的口径。当对比 P50/P90、解释认证系数或爬坡折减时使用。不适用：产能数值计算本身（应由 capacity_forecast 求解器计算）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YQHBHEQZRJ07A79W5CH', 'demo', 's02_affected', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YQHBHEQZRJ07A79W5CH", "key": "s02_affected", "body": "## 目的\n解读交期风险扫描结果。\n## 适用边界\n适用：说明哪些订单受影响、解释窗口口径时。不适用：单订单承接性测算（用 s01）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "受影响订单解读", "status": "PUBLISHED", "summary": "解读交期风险扫描结果。当说明哪些订单受影响、解释窗口口径时使用。不适用：单订单承接性测算（用 s01）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YQVNC6XF7KHGKAXH7KS', 'demo', 's03_rootcause', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YQVNC6XF7KHGKAXH7KS", "key": "s03_rootcause", "body": "## 目的\n解释风险越线的根因与时序。\n## 适用边界\n适用：用户问为什么这天越线、峰值多高、什么事件推的时。不适用：给处置方案（用 s06）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "风险越线根因解读", "status": "PUBLISHED", "summary": "解释风险越线的根因与时序。当用户问为什么这天越线、峰值多高、什么事件推的时使用。不适用：给处置方案（用 s06）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YR5N7HC9PQF12SQ723K', 'demo', 's04_audit', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YR5N7HC9PQF12SQ723K", "key": "s04_audit", "body": "## 目的\n解读规划体检结论。\n## 适用边界\n适用：解释硬矛盾软风险条目、说明评分与修正建议时。不适用：直接改计划（fix 仅演示，生效走审批）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "规划体检解读", "status": "PUBLISHED", "summary": "解读规划体检结论。当解释硬矛盾软风险条目、说明评分与修正建议时使用。不适用：直接改计划（fix 仅演示，生效走审批）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YREAGMM5SHV0S0BK3DR', 'demo', 's05_plan', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YREAGMM5SHV0S0BK3DR", "key": "s05_plan", "body": "## 目的\n解读三方案比选。\n## 适用边界\n适用：解释推荐理由、五维取舍、硬约束违反时。不适用：替用户拍板（系统只算路径与后果）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "经营方案比选解读", "status": "PUBLISHED", "summary": "解读三方案比选。当解释推荐理由、五维取舍、硬约束违反时使用。不适用：替用户拍板（系统只算路径与后果）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YRQZKV3NEKFVAVKJ4HW', 'demo', 's06_mitigation', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YRQZKV3NEKFVAVKJ4HW", "key": "s06_mitigation", "body": "## 目的\n协助采纳风险处置方案。\n## 适用边界\n适用：用户说采纳、就用某方案、下单处理时。不适用：比较方案优劣（本技能只执行采纳）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "处置方案采纳协助", "status": "PUBLISHED", "summary": "协助采纳风险处置方案。当用户说采纳、就用某方案、下单处理时使用。不适用：比较方案优劣（本技能只执行采纳）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YS0506ET4NTAB30X7CA', 'demo', 's07_cert', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YS0506ET4NTAB30X7CA", "key": "s07_cert", "body": "## 目的\n解读认证排期建议。\n## 适用边界\n适用：问先认证哪个、何时完成、解锁多少产能时。不适用：修改认证状态（PLM 域职责）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "认证排期解读", "status": "PUBLISHED", "summary": "解读认证排期建议。当问先认证哪个、何时完成、解锁多少产能时使用。不适用：修改认证状态（PLM 域职责）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YS8XCBBJBWE5WWN4HC7', 'demo', 's08_kit', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YS8XCBBJBWE5WWN4HC7", "key": "s08_kit", "body": "## 目的\n解读物料齐套分析。\n## 适用边界\n适用：问哪些单开不了工、缺什么料、何时补齐时。不适用：直接下采购单（给建议）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "齐套分析解读", "status": "PUBLISHED", "summary": "解读物料齐套分析。当问哪些单开不了工、缺什么料、何时补齐时使用。不适用：直接下采购单（给建议）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YSJVY9B9BKHR7FSXAW9', 'demo', 's09_lta', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YSJVY9B9BKHR7FSXAW9", "key": "s09_lta", "body": "## 目的\n解读长协覆盖与补缺。\n## 适用边界\n适用：问长协够不够、现货要补多少、何时下单时。不适用：长协条款变更（年度 AOP 决策）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "长协补缺解读", "status": "PUBLISHED", "summary": "解读长协覆盖与补缺。当问长协够不够、现货要补多少、何时下单时使用。不适用：长协条款变更（年度 AOP 决策）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YSWRN7AT9FWJTS2WA29', 'demo', 's10_inventory', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YSWRN7AT9FWJTS2WA29", "key": "s10_inventory", "body": "## 目的\n解读库存优化清单。\n## 适用边界\n适用：问哪些超储欠储呆滞、能释放多少资金时。不适用：执行调拨（建议态）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "库存优化解读", "status": "PUBLISHED", "summary": "解读库存优化清单。当问哪些超储欠储呆滞、能释放多少资金时使用。不适用：执行调拨（建议态）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YT567BWZ2N84RBZTSAY', 'demo', 's11_changeover', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YT567BWZ2N84RBZTSAY", "key": "s11_changeover", "body": "## 目的\n解读换型排序建议。\n## 适用边界\n适用：问怎么排单换型最少、能省多少时间时。不适用：冻结期内重排（须走变更 Action）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "换型排序解读", "status": "PUBLISHED", "summary": "解读换型排序建议。当问怎么排单换型最少、能省多少时间时使用。不适用：冻结期内重排（须走变更 Action）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YTE10YHAM5MWR0QBFW3', 'demo', 's12_yield', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YTE10YHAM5MWR0QBFW3", "key": "s12_yield", "body": "## 目的\n解读良率波动诊断。\n## 适用边界\n适用：问良率为什么掉、从哪天开始、疑似什么原因时。不适用：判定责任（定责走质量流程）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "良率诊断解读", "status": "PUBLISHED", "summary": "解读良率波动诊断。当问良率为什么掉、从哪天开始、疑似什么原因时使用。不适用：判定责任（定责走质量流程）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YTRCHG88A625K55FG76', 'demo', 's13_maint', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YTRCHG88A625K55FG76", "key": "s13_maint", "body": "## 目的\n解读检修错峰建议。\n## 适用边界\n适用：问检修和交付撞期怎么办、挪到哪周时。不适用：直接改检修计划（EAM 域）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "检修错峰解读", "status": "PUBLISHED", "summary": "解读检修错峰建议。当问检修和交付撞期怎么办、挪到哪周时使用。不适用：直接改检修计划（EAM 域）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YV1WPP37QWKVBE8J2MZ', 'demo', 's14_outsourcing', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YV1WPP37QWKVBE8J2MZ", "key": "s14_outsourcing", "body": "## 目的\n解读外协分配方案。\n## 适用边界\n适用：问加班还是外协、各多少、成本差异时。不适用：选外协厂（采购域职责）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "外协分配解读", "status": "PUBLISHED", "summary": "解读外协分配方案。当问加班还是外协、各多少、成本差异时使用。不适用：选外协厂（采购域职责）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YVA7D5SABCRRAHENX7F', 'demo', 's15_quote', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YVA7D5SABCRRAHENX7F", "key": "s15_quote", "body": "## 目的\n解读接单毛利评审。\n## 适用边界\n适用：问这单毛利过不过线、成本怎么构成时。不适用：调价谈判策略（给数据不给话术）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "接单毛利解读", "status": "PUBLISHED", "summary": "解读接单毛利评审。当问这单毛利过不过线、成本怎么构成时使用。不适用：调价谈判策略（给数据不给话术）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YVKW23V7CXTDJ6XZ3E4', 'demo', 's16_credit', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YVKW23V7CXTDJ6XZ3E4", "key": "s16_credit", "body": "## 目的\n解读客户信用判定。\n## 适用边界\n适用：问还能不能接某客户新单、敞口多大时。不适用：调整信用额度（财务域审批）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "客户信用解读", "status": "PUBLISHED", "summary": "解读客户信用判定。当问还能不能接某客户新单、敞口多大时使用。不适用：调整信用额度（财务域审批）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YVW6YE1HKACJ6JVAQ0E', 'demo', 's17_capex', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YVW6YE1HKACJ6JVAQ0E", "key": "s17_capex", "body": "## 目的\n解读产能投资评审。\n## 适用边界\n适用：问值不值得投、IRR 多少、利用率预测时。不适用：替投委会决策（C23 是门槛非批准）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "产能投资解读", "status": "PUBLISHED", "summary": "解读产能投资评审。当问值不值得投、IRR 多少、利用率预测时使用。不适用：替投委会决策（C23 是门槛非批准）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YW5VPEHGEXZMQAAH5BQ', 'demo', 's18_sop', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YW5VPEHGEXZMQAAH5BQ", "key": "s18_sop", "body": "## 目的\n解读 S&OP 进度与平衡状态。\n## 适用边界\n适用：问走到第几步、缺口多少、哪些要上会时。不适用：代行第五步决策。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "S&OP 进度解读", "status": "PUBLISHED", "summary": "解读 S&OP 进度与平衡状态。当问走到第几步、缺口多少、哪些要上会时使用。不适用：代行第五步决策。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YWFMPP2J865802KGY13', 'demo', 's19_qgap', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YWFMPP2J865802KGY13", "key": "s19_qgap", "body": "## 目的\n解读季度缺口对策组合。\n## 适用边界\n适用：问某季缺口怎么补、组合成本时。不适用：执行单项对策（跳对应场景）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "季度缺口对策解读", "status": "PUBLISHED", "summary": "解读季度缺口对策组合。当问某季缺口怎么补、组合成本时使用。不适用：执行单项对策（跳对应场景）。", "version": 1, "tenantId": "demo", "resources": []}');
INSERT INTO "public"."skills" VALUES ('skl_01KV2B8YWR5CM22HBWF858M7YA', 'demo', 's20_carbon', 1, 'PUBLISHED', '{"id": "skl_01KV2B8YWR5CM22HBWF858M7YA", "key": "s20_carbon", "body": "## 目的\n解读碳足迹核算。\n## 适用边界\n适用：问碳足迹多少、达不达标、怎么降时。不适用：申报文件制作（合规域）。\n## 前置检查\n确认求解结果的 snapshotVersion 与入参回显一致；选中对象与问句指代一致。\n## 步骤\n1. 按口径逐项核对并代入数值。\n2. 结论句给出判定与主要驱动项。\n## 示例\n正例：用户问对应问题→逐口径解释并挂溯源角标。\n反例：只报结论不报证据链（错：结论必须可溯源）。\n## 失败处理\n求解器返回错误码→转述错误并给下一步，禁止编造结果。\n## 输出要求\n每个数字挂溯源角标；结论句含判定与主要驱动项。", "name": "碳足迹解读", "status": "PUBLISHED", "summary": "解读碳足迹核算。当问碳足迹多少、达不达标、怎么降时使用。不适用：申报文件制作（合规域）。", "version": 1, "tenantId": "demo", "resources": []}');


