INSERT INTO "public"."workflows" VALUES ('wf_seed_capacity', 'demo', 'capacity_check', 1, 'PUBLISHED', '{"id": "wf_seed_capacity", "key": "capacity_check", "name": "产能校核流程", "steps": [{"id": "s1", "type": "query_objects", "params": {"filter": {}, "objectType": "Model"}}, {"id": "s2", "type": "invoke_solver", "params": {"args": {"weeks": "{{slots.weeks}}", "modelId": "{{slots.model}}", "demandDelta": "{{slots.demandDelta}}"}, "solverKey": "capacity_forecast"}}, {"id": "s3", "type": "evaluate_rules", "params": {"payload": {"demandDelta": "{{slots.demandDelta}}"}, "ruleIds": ["C03"]}}, {"id": "s4", "type": "render_answer", "params": {"blocks": [{"type": "text", "markdown": "产能校核结论（见步骤溯源）"}]}}], "inputs": {"type": "object", "properties": {"model": {"type": "string"}, "weeks": {"type": "number"}, "demandDelta": {"type": "number"}}}, "status": "PUBLISHED", "version": 1, "tenantId": "demo", "createdAt": "2026-06-14T05:53:39.577Z", "updatedAt": "2026-06-14T05:53:39.577Z", "description": "型号需求增量可行性校核（resolve → solve → rules → render）"}');


